def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float)
    ids = list(feats.ids); n, p = X.shape
    X = (X - X.mean(0)) / (X.std(0) + 1e-9)
    yc = y - y.mean(); sy = (yc @ yc) ** .5 + 1e-12

    def tst(v):                                   # |t| of corr(v, y)
        c = np.clip(v @ yc / ((v @ v) ** .5 * sy + 1e-12), -.9999, .9999)
        return float(abs(c) * ((n - 2) / (1 - c * c)) ** .5)

    def fit(D):                                   # coef t-stats of OLS yc ~ D
        b = np.linalg.lstsq(D, yc, rcond=None)[0]
        s = yc - D @ b
        v = np.linalg.pinv(D.T @ D) * (s @ s / max(n - D.shape[1], 1))
        return b / np.sqrt(np.diag(v) + 1e-12)

    t = np.array([tst(X[:, j]) for j in range(p)])
    order = np.argsort(-t)
    hits = [int(j) for j in order if stats.t.sf(t[j], n - 2) * p < .025]
    C = np.abs(X.T @ X) / n; np.fill_diagonal(C, 0)

    seen = np.zeros(p, bool); loadings = {}; smem = []
    for j in order:                               # correlated clusters -> PC1 score
        if seen[j] or not (C[j] >= .8).any():
            continue
        comp, k, seen[j] = [int(j)], 0, True
        while k < len(comp):
            for m in np.where(C[comp[k]] >= .8)[0]:
                if not seen[m]:
                    seen[m] = True; comp.append(int(m))
            k += 1
        if len(comp) < 3:
            continue
        w = np.linalg.eigh(np.corrcoef(X[:, comp].T))[1][:, -1]
        w *= np.sign(w @ (X[:, comp].T @ yc)) or 1
        if tst(X[:, comp] @ w) > 3.5:
            loadings = {ids[m]: float(w[i]) for i, m in enumerate(comp)}
            smem = [comp[i] for i in np.argsort(-t[comp])[:3]]

    cand = []
    if p <= 600:                                  # all-pairs product scan
        for a in range(p):
            Z = X * X[:, a:a + 1]
            cz = np.clip((Z.T @ yc) / ((Z ** 2).sum(0) ** .5 * sy + 1e-12), -.9999, .9999)
            tz = np.abs(cz) * ((n - 2) / (1 - cz ** 2)) ** .5
            for b in np.where(tz > 4.7)[0]:
                if b > a and C[a, b] < .8:
                    cand.append((float(tz[b]), a, int(b)))
    prods, ppairs, ev = [], [], {}
    for _, a, b in sorted(cand, reverse=True)[:20]:
        D = np.column_stack([np.ones(n), X[:, a], X[:, b], X[:, a] * X[:, b]])
        tt = fit(D)
        if abs(tt[3]) > 4.5:
            prods.append((ids[a], ids[b])); ppairs.append((a, b))
            ev[a] = max(ev.get(a, 0), abs(tt[3])); ev[b] = max(ev.get(b, 0), abs(tt[3]))
        if len(prods) >= 5:
            break

    reps = []                                     # dedup hits vs stronger picks
    for j in hits:
        if all(C[j, k] < .8 for k in reps):
            reps.append(j)
    surv = list(reps)                             # joint-model prune of correlates
    if len(surv) > 1:
        tt = fit(X[:, surv])
        surv = [surv[i] for i in range(len(surv)) if abs(tt[i]) >= 2] or surv[:1]
    for j in surv:
        ev[j] = max(ev.get(j, 0), t[j])
    for j in smem:
        ev[j] = max(ev.get(j, 0), t[j])
    if not (surv or prods or loadings):
        return Design(drivers=(), columns=(), products=(), loadings={})
    cols = list(surv)
    for a, b in ppairs:
        cols += [j for j in (a, b) if j not in cols]
    drivers = tuple(ids[j] for j in sorted(ev, key=ev.get, reverse=True)[:MAX_DRIVERS])
    return Design(drivers=drivers, columns=tuple(ids[j] for j in cols[:20]),
                  products=tuple(prods), loadings=loadings)

